struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float2 hash2(float2 p)
{
    p = float2(dot(p, float2(127.1, 311.7)), dot(p, float2(269.5, 183.3)));
    return frac(sin(p) * 43758.5453);
}

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001;
    float2 uv = i.uv * 6.0;
    float2 ip = floor(uv);
    float2 fp = frac(uv);
    float minDist = 10.0;
    float2 minPoint = float2(0, 0);
    float minId = 0.0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            float2 neighbor = float2(x, y);
            float2 point = hash2(ip + neighbor);
            point = 0.5 + 0.5 * sin(t + 6.2831 * point);
            float2 diff = neighbor + point - fp;
            float d = length(diff);
            if (d < minDist) {
                minDist = d;
                minPoint = point;
                minId = dot(ip + neighbor, float2(7.0, 113.0));
            }
        }
    }
    float3 col = 0.5 + 0.5 * sin(minId * float3(1.2, 2.3, 3.4) + float3(0, 1, 2));
    col *= 1.0 - 0.4 * smoothstep(0.0, 0.05, minDist - 0.02);
    col *= 0.8 + 0.2 * smoothstep(0.0, 0.02, minDist);
    return float4(col, 1.0);
}
